import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), m = sc.nextInt();
        long x = sc.nextLong();
        long[] pizza = new long[n], top = new long[m];
        for (int i = 0; i < n; i++) pizza[i] = sc.nextLong();
        for (int i = 0; i < m; i++) top[i] = sc.nextLong();
        // Topping sums for 0, 1 or 2 distinct toppings.
        List<Long> extras = new ArrayList<>();
        extras.add(0L);
        for (int i = 0; i < m; i++) extras.add(top[i]);
        for (int i = 0; i < m; i++)
            for (int j = i + 1; j < m; j++) extras.add(top[i] + top[j]);
        long ans = pizza[0];
        for (long p : pizza)
            for (long e : extras) {
                long c = p + e, dc = Math.abs(c - x), da = Math.abs(ans - x);
                // Smaller distance to the budget first, then the lower price.
                if (dc < da || (dc == da && c < ans)) ans = c;
            }
        System.out.println(ans);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func abs(v int64) int64 {
	if v < 0 {
		return -v
	}
	return v
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, m int
	var x int64
	fmt.Fscan(in, &n, &m, &x)
	pizza, top := make([]int64, n), make([]int64, m)
	for i := range pizza {
		fmt.Fscan(in, &pizza[i])
	}
	for i := range top {
		fmt.Fscan(in, &top[i])
	}
	// Topping sums for 0, 1 or 2 distinct toppings.
	extras := append([]int64{0}, top...)
	for i := 0; i < m; i++ {
		for j := i + 1; j < m; j++ {
			extras = append(extras, top[i]+top[j])
		}
	}
	ans := pizza[0]
	for _, p := range pizza {
		for _, e := range extras {
			c := p + e
			dc, da := abs(c-x), abs(ans-x)
			// Smaller distance to the budget first, then the lower price.
			if dc < da || (dc == da && c < ans) {
				ans = c
			}
		}
	}
	fmt.Println(ans)
}
